/**
 * Unit tests for Phoneme.toString()
 */
public class Phoneme_toString_TriageGen2Test {

    @Test
    public void testToStringWithSinglePhoneme() {
        // Arrange
        CharSequence text = "abc";
        Languages.LanguageSet languages = Languages.LanguageSet.EMPTY;
        Phoneme phoneme = new Phoneme(text, languages);

        // Act
        String result = phoneme.toString();

        // Assert
        // Expected format: phonemeText.toString() + "[" + languages + "]"
        assertEquals("abc[[]", result);
    }

    @Test
    public void testToStringWithSpecificLanguages() {
        // Arrange
        // Note: Languages.LanguageSet behavior depends on implementation, 
        // but we test the string concatenation logic.
        CharSequence text = "xyz";
        // Using a mock-like approach with an existing set if possible, 
        // but since we use the constructor, we'll use a known set.
        Languages.LanguageSet languages = Languages.LanguageSet.EMPTY; 
        Phoneme phoneme = new Phoneme(text, languages);

        // Act
        String result = phoneme.toString();

        // Assert
        assertEquals("xyz[[]", result);
    }

    @Test
    public void testToStringWithJoinedPhonemes() {
        // Arrange
        Phoneme p1 = new Phoneme("a", Languages.LanguageSet.EMPTY);
        Phoneme p2 = new Phoneme("b", Languages.LanguageSet.EMPTY);

        // Using the constructor: public Phoneme(final Phoneme phonemeLeft, final Phoneme phonemeRight)
        // This likely results in a combined phonemeText
        Phoneme joined = new Phoneme(p1, p2);

        // Act
        String result = joined.toString();

        // Assert
        // The exact string depends on how join/constructor handles phonemeText,
        // but we ensure the toString method executes the concatenation logic.
        // Assuming join/constructor concatenates "a" and "b" -> "ab"
        // and languages is likely empty or inherited.
        String expectedPrefix = joined.getPhonemeText().toString();
        String expectedSuffix = "[" + joined.getLanguages() + "]";
        assertEquals(expectedPrefix + expectedSuffix, result);
    }

    @Test
    public void testToStringWithThreeParamConstructor() {
        // Arrange
        Phoneme p1 = new Phoneme("a", Languages.LanguageSet.EMPTY);
        Phoneme p2 = new Phoneme("b", Languages.LanguageSet.EMPTY);
        Languages.LanguageSet languages = Languages.LanguageSet.EMPTY;

        // Using the constructor: public Phoneme(final Phoneme phonemeLeft, final Phoneme phonemeRight, final Languages.LanguageSet languages)
        Phoneme phoneme = new Phoneme(p1, p2, languages);

        // Act
        String result = phoneme.toString();

        // Assert
        String expectedText = phoneme.getPhonemeText().toString();
        String expectedLang = "[" + languages + "]";
        assertEquals(expectedText + expectedLang, result);
    }
}
